#!/usr/bin/env node
// Regenerate two artifacts from the file system, in lockstep:
//   1. package.json "exports" map — per-entry subpaths
//   2. src/index.ts barrel       — root re-exports
//
// Source of truth: three sibling namespace directories under src/.
//   components/<name>/  → "./<name>"            (flat subpath, primary surface)
//   hooks/<name>        → "./hooks/<name>"
//   providers/<name>    → "./providers/<name>"
//
// Each entry can be either a folder (preferred when there are co-located
// files like tests) or a single file:
//   - <namespace>/<name>/<name>.{ts,tsx}        (folder, single-primitive)
//   - <namespace>/<name>/index.{ts,tsx}         (folder, compound aggregator)
//   - <namespace>/<name>.{ts,tsx}               (flat file)
//
// Static "exports" entries (".", "./styles.css", "./package.json") are
// preserved. The barrel uses `export * from '...'` so each entry file
// owns its public surface — anything exported there leaks into the barrel.
//
// Run via `pnpm sync-exports`, or automatically via `prebuild` / `prepack`.

import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join, dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const PKG_DIR = resolve(__dirname, '..')
const SRC_DIR = join(PKG_DIR, 'src')
const PKG_PATH = join(PKG_DIR, 'package.json')
const BARREL_PATH = join(SRC_DIR, 'index.ts')

// Namespace → subpath prefix. "" means flat at root (e.g. "./checkbox").
const NAMESPACES = [
  { dir: 'components', subpathPrefix: '' },
  { dir: 'hooks', subpathPrefix: 'hooks/' },
  { dir: 'providers', subpathPrefix: 'providers/' },
]

const BARREL_BANNER =
  '// Auto-generated by scripts/sync-exports.mjs from src/{components,hooks,providers}/*.\n' +
  '// Do not edit by hand — your changes will be overwritten on the next build.\n\n'

// Resolve an entry to its import path under the namespace dir (no extension),
// or null if the entry doesn't exist. The returned path is what goes after
// `./<namespace>/` in barrel imports and `./dist/<namespace>/` in exports.
//
//   folder + <name>/<name>.tsx   → "<name>/<name>"
//   folder + <name>/index.tsx    → "<name>/index"
//   flat   + <name>.ts           → "<name>"
function resolveEntry(namespaceDir, name) {
  const nsDir = join(SRC_DIR, namespaceDir)
  const folder = join(nsDir, name)
  if (existsSync(folder)) {
    if (existsSync(join(folder, 'index.tsx')) || existsSync(join(folder, 'index.ts'))) {
      return `${name}/index`
    }
    if (existsSync(join(folder, `${name}.tsx`)) || existsSync(join(folder, `${name}.ts`))) {
      return `${name}/${name}`
    }
  }
  if (existsSync(join(nsDir, `${name}.tsx`)) || existsSync(join(nsDir, `${name}.ts`))) {
    return name
  }
  return null
}

const ENTRY_FILE_RE = /\.(tsx?)$/
const TEST_FILE_RE = /\.test\.(tsx?)$/

function listEntries(namespaceDir) {
  const dir = join(SRC_DIR, namespaceDir)
  if (!existsSync(dir)) return []
  const names = new Set()
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      names.add(e.name)
    } else if (e.isFile() && ENTRY_FILE_RE.test(e.name) && !TEST_FILE_RE.test(e.name)) {
      names.add(e.name.replace(ENTRY_FILE_RE, ''))
    }
  }
  return [...names]
    .map((name) => ({ name, importPath: resolveEntry(namespaceDir, name) }))
    .filter((e) => e.importPath !== null)
    .sort((a, b) => a.name.localeCompare(b.name))
}

function collectAll() {
  return NAMESPACES.map(({ dir, subpathPrefix }) => ({
    dir,
    subpathPrefix,
    entries: listEntries(dir),
  }))
}

function buildExports(namespaces) {
  const exports = {
    '.': {
      types: './dist/index.d.ts',
      import: './dist/index.js',
      default: './dist/index.js',
    },
  }
  for (const { dir, subpathPrefix, entries } of namespaces) {
    for (const { name, importPath } of entries) {
      exports[`./${subpathPrefix}${name}`] = {
        types: `./dist/${dir}/${importPath}.d.ts`,
        import: `./dist/${dir}/${importPath}.js`,
        default: `./dist/${dir}/${importPath}.js`,
      }
    }
  }
  exports['./styles.css'] = './styles.css'
  exports['./package.json'] = './package.json'
  return exports
}

function buildBarrel(namespaces) {
  const lines = []
  for (const { dir, entries } of namespaces) {
    for (const { importPath } of entries) {
      lines.push(`export * from './${dir}/${importPath}'`)
    }
  }
  return BARREL_BANNER + lines.join('\n') + '\n'
}

function summarize(namespaces) {
  const parts = namespaces
    .filter((n) => n.entries.length > 0)
    .map((n) => `${n.entries.length} ${n.dir}: ${n.entries.map((e) => e.name).join(', ')}`)
  return parts.length > 0 ? parts.join(' | ') : 'no entries'
}

function main() {
  const check = process.argv.includes('--check')
  const namespaces = collectAll()
  const updates = []

  // package.json exports
  const pkg = JSON.parse(readFileSync(PKG_PATH, 'utf8'))
  const nextExports = buildExports(namespaces)
  if (JSON.stringify(pkg.exports) !== JSON.stringify(nextExports)) {
    if (!check) {
      pkg.exports = nextExports
      writeFileSync(PKG_PATH, JSON.stringify(pkg, null, 2) + '\n')
    }
    updates.push('package.json:exports')
  }

  // src/index.ts barrel
  const nextBarrel = buildBarrel(namespaces)
  const currentBarrel = existsSync(BARREL_PATH) ? readFileSync(BARREL_PATH, 'utf8') : ''
  if (currentBarrel !== nextBarrel) {
    if (!check) writeFileSync(BARREL_PATH, nextBarrel)
    updates.push('src/index.ts')
  }

  const summary = summarize(namespaces)
  if (updates.length === 0) {
    console.log(`✓ in sync (${summary})`)
  } else if (check) {
    console.error(`✗ out of sync: ${updates.join(' + ')} — run \`pnpm sync-exports\` (${summary})`)
    process.exit(1)
  } else {
    console.log(`✓ regenerated ${updates.join(' + ')} (${summary})`)
  }
}

main()
